        vm.prank(owner);
        token.setRewardsPool(address(0));

        vm.prank(owner);
        vm.expectRevert("please set rewardsPool");
        token.rebase(2);
    }

    function testRebaseFailsWithUnsetPair() public {
        vm.prank(owner);
        token.setPair(address(0));

        vm.prank(owner);
        vm.expectRevert();
        token.rebase(2);
    }

