        uint initialSyncCount = mockPair.syncCalled();

        vm.prank(owner);
        token.rebase(2);

        uint newSyncCount = mockPair.syncCalled();
        assertEq(newSyncCount, initialSyncCount + 1, "Sync not called");
    }
}
